def getHappyString(n: int, k: int) -> str:
    if k > 3 * 2**(n - 1):
        return ""

    def backtrack(path):
        if len(path) == n:
            return [path]
        result = []
        for char in 'abc':
            if not path or path[-1] != char:
                result.extend(backtrack(path + char))
        return result

    happy_strings = backtrack("")
    return happy_strings[k-1] if k <= len(happy_strings) else ""
